text = text.replace(marker, landing + marker, 1)

# Sanity checks keep the build from deploying a half-wired page.
for required in [
    "mode==='landing'",
    'ثبت‌نام اولیه نمایندگی',
    'name="action" value="register"',
    'name="password_confirm"',
    'name="terms"',
    'رمز ورود ۴ رقمی',
    'ساخت پنل و شروع فعالیت',
    'مرا به خاطر بسپار',
]:
    if required not in text:
        raise SystemExit('public landing invariant missing: ' + required)

index_path.write_text(text, encoding='utf-8')

